#include <string>
#include <set>
#include <utility>

class Solution {
public:
    bool isPathCrossing(std::string path) {
        std::set<std::pair<int, int>> visited;
        int x = 0, y = 0;
        visited.insert({0, 0});
        for (char c : path) {
            if (c == 'N') y++;
            else if (c == 'S') y--;
            else if (c == 'E') x++;
            else if (c == 'W') x--;
            if (visited.count({x, y})) return true;
            visited.insert({x, y});
        }
        return false;
    }
};

import java.util.*;

class Solution {
    public boolean isPathCrossing(String path) {
        Set<String> visited = new HashSet<>();
        int x = 0, y = 0;
        visited.add("0,0");
        for (char c : path.toCharArray()) {
            if (c == 'N') y++;
            else if (c == 'S') y--;
            else if (c == 'E') x++;
            else if (c == 'W') x--;
            String key = x + "," + y;
            if (visited.contains(key)) return true;
            visited.add(key);
        }
        return false;
    }
}

var isPathCrossing = function(path) {
